    if sparsify is not None:
        if isinstance(sparsify, tuple):
            if len(sparsify) != 2 or not isinstance(sparsify[1], dict):
                raise ValueError('sparsify tuple must be (method, options)')
            sparsify_method, sparsify_kwargs = sparsify
            if sparsify_method not in ('sparsify',
