                raise ValueError(f'Unknown sparsify method {sparsify_method}')
            sparsify_kwargs = dict(sparsify_kwargs)
        else:
            if isinstance(sparsify, (bool, np.bool_)):
                if not sparsify:
                    sparsify_kwargs = None
                else:
                    sparsify_kwargs = {}
            elif np.isscalar(sparsify):
                if isinstance(sparsify, (str, bytes)):
                    raise ValueError('invalid sparsify option')
